def test_daily_conversion_counts_fills_gaps_and_ignores_out_of_range():
    events = parse_session_log(["a,2,1", "b,2,1", "c,3,0", "d,4,", "e,5,1", "f,1,1", "g,6,1"])
    assert daily_conversion_counts(events, 2, 5) == [2, 0, 0, 1]
